#!/usr/bin/env python3
"""Describe the exact Unity ParticleSystem bindings generated by QPM for CI.
This diagnoses compile-time API differences; no device settings are changed.
"""
from pathlib import Path
import re
p = Path("extern/includes/bs-cordl/include/UnityEngine/zzzz__ParticleSystem_def.hpp")
if not p.exists():
    raise SystemExit(f"Missing generated header: {p}")
text = p.read_text(encoding="utf-8")
for name in ("ParticleSystem_MainModule", "ParticleSystem_EmissionModule",
             "ParticleSystem_ShapeModule", "ParticleSystem_CollisionModule",
             "ParticleSystem_TextureSheetAnimationModule",
             "ParticleSystem_ColorOverLifetimeModule", "ParticleSystem_ColorBySpeedModule",
             "ParticleSystem_MinMaxCurve", "ParticleSystem_MinMaxGradient"):
    start = text.find("struct CORDL_TYPE " + name)
    if start < 0:
        print("BINDING NOT FOUND:", name)
        continue
    end = text.find("\n};", start)
    section = text[start:end if end >= 0 else start + 10000]
    matches = [x.strip() for x in section.splitlines()
               if re.search(r"\b(set_|get_|New_ctor|_ctor|m_Constant|m_Color|m_Mode)", x)]
    print(f"--- {name}: {len(matches)} matching declarations ---")
    for line in matches[:110]:
        print(line[:250])
